<?php
namespace App\Http\Controllers;
use App\Jobs\ProcessChoiceOptimizationGoogleFormMerge;use App\Jobs\ProcessChoiceOptimizationGoogleFormValidation;use App\Models\ChoiceOptimizationGoogleFormBatch;use App\Services\ChoiceOptimization\ChoiceOptimizationGoogleFormDecisionService;use App\Services\ChoiceOptimization\ChoiceOptimizationGoogleFormImportService;use App\Services\ChoiceOptimization\ChoiceOptimizationGoogleFormInvalidExportService;use App\Services\ChoiceOptimization\ChoiceOptimizationSettingsService;use App\Support\Examinations\ExaminationContext;use Illuminate\Http\JsonResponse;use Illuminate\Http\RedirectResponse;use Illuminate\Http\Request;use Illuminate\Support\Facades\File;use Illuminate\View\View;use Symfony\Component\HttpFoundation\BinaryFileResponse;
final class ChoiceOptimizationGoogleFormController extends Controller
{
    public function decision(Request $request,ChoiceOptimizationSettingsService $settings,ChoiceOptimizationGoogleFormDecisionService $service):RedirectResponse{$this->assertOptimizationEnabled($settings);$v=$request->validate(['google_form_enabled'=>['required','in:0,1']]);$enabled=$v['google_form_enabled']==='1';$service->update($enabled,$request->user()?->getAuthIdentifier());return back()->with('success',$enabled?'Google Form historical recommendation step enabled.':'Google Form step intentionally bypassed; it will not gate downstream optimization.');}
    public function upload(Request $request,ChoiceOptimizationSettingsService $settings,ChoiceOptimizationGoogleFormImportService $service,ExaminationContext $context):RedirectResponse{$this->assertGoogleFormEnabled($settings);$v=$request->validate(['file'=>['required','file','mimes:xlsx,csv','max:102400']]);$examId=$context->currentId();abort_if($examId===null,409,'No examination is selected.');$batch=$service->enqueue($v['file'],(int)$request->user()->id,(int)$examId);return redirect()->route('choice-optimization.google-form.show',$batch)->with('success','Google Form file queued for staging.');}
    public function show(ChoiceOptimizationSettingsService $settings,ChoiceOptimizationGoogleFormBatch $batch,Request $request):View{$this->assertGoogleFormEnabled($settings);$status=(string)$request->query('status','');$rows=$batch->rows()->when($status!=='',fn($q)=>$q->where('validation_status',$status))->orderBy('source_row')->paginate(100)->withQueryString();$isLatestBatch=(int)$batch->id===(int)(ChoiceOptimizationGoogleFormBatch::query()->max('id')??0);return view('choice-optimization.google-form-show',compact('batch','rows','status','isLatestBatch'));}
    public function status(ChoiceOptimizationSettingsService $settings,ChoiceOptimizationGoogleFormBatch $batch):JsonResponse{$this->assertGoogleFormEnabled($settings);$batch->refresh();$status=(string)$batch->status;$running=in_array($status,['queued','processing','validation_queued','validating','merge_queued','merging'],true);$phase=match($status){'queued','processing'=>'Staging','validation_queued','validating'=>'Validation','merge_queued','merging'=>'Merge',default=>'Completed'};$current=match($status){'merge_queued','merging'=>(int)$batch->processed_rows,default=>(int)$batch->processed_rows};$target=match($status){'merge_queued','merging'=>max(0,(int)$batch->valid_rows),default=>max(0,(int)$batch->total_rows)};return response()->json(['status'=>$status,'status_label'=>strtoupper(str_replace('_',' ',$status)),'phase'=>$phase,'current'=>$current,'target'=>$target,'total_rows'=>(int)$batch->total_rows,'processed_rows'=>(int)$batch->processed_rows,'valid_rows'=>(int)$batch->valid_rows,'invalid_rows'=>(int)$batch->invalid_rows,'merged_rows'=>(int)$batch->merged_rows,'progress_percent'=>(float)$batch->progress_percent,'failure_message'=>$batch->failure_message,'running'=>$running,'finished'=>!$running]);}
    public function validateBatch(Request $request,ChoiceOptimizationSettingsService $settings,ChoiceOptimizationGoogleFormBatch $batch,ExaminationContext $context):RedirectResponse{$this->assertGoogleFormEnabled($settings);$latestBatchId=(int)(ChoiceOptimizationGoogleFormBatch::query()->max('id')??0);abort_unless((int)$batch->id===$latestBatchId,409,'Only the latest Google Form batch can be validated. Older batches are history only.');abort_unless(in_array((string)$batch->status,['staged','validation_failed'],true),409,'Only a staged Google Form batch can be validated.');$examId=$context->currentId();abort_if($examId===null,409,'No examination is selected.');$batch->update(['status'=>'validation_queued','processed_rows'=>0,'progress_percent'=>0,'failure_message'=>null,'finished_at'=>null]);ProcessChoiceOptimizationGoogleFormValidation::dispatch((int)$examId,(int)$batch->id,(int)$request->user()->id);return back()->with('success','Google Form validation queued.');}
    public function mergeValid(Request $request,ChoiceOptimizationSettingsService $settings,ChoiceOptimizationGoogleFormBatch $batch,ExaminationContext $context):RedirectResponse{$this->assertGoogleFormEnabled($settings);abort_unless((string)$batch->status==='validated',409,'Only a validated Google Form batch can be merged.');$latestBatchId=(int)(ChoiceOptimizationGoogleFormBatch::query()->max('id')??0);abort_unless((int)$batch->id===$latestBatchId,409,'Only the latest Google Form batch can be approved/merged. Older batches are history only.');abort_if((int)$batch->valid_rows<1,409,'This batch has no valid rows to merge.');$examId=$context->currentId();abort_if($examId===null,409,'No examination is selected.');$batch->update(['status'=>'merge_queued','processed_rows'=>0,'progress_percent'=>0,'failure_message'=>null,'finished_at'=>null]);ProcessChoiceOptimizationGoogleFormMerge::dispatch((int)$examId,(int)$batch->id,(int)$request->user()->id);return back()->with('success','Valid Google Form rows queued for merge. Invalid rows will remain available for download/correction.');}
    public function invalidRows(ChoiceOptimizationSettingsService $settings,ChoiceOptimizationGoogleFormBatch $batch,ChoiceOptimizationGoogleFormInvalidExportService $service):BinaryFileResponse{$this->assertGoogleFormEnabled($settings);$dir=storage_path('app/private/choice-optimization/google-form');File::ensureDirectoryExists($dir);$path=$dir.'/google-form-batch-'.$batch->id.'-invalid-rows.xlsx';$count=$service->create($batch,$path);abort_if($count===0,409,'This batch has no invalid rows.');return response()->download($path,basename($path))->deleteFileAfterSend();}
    private function assertOptimizationEnabled(ChoiceOptimizationSettingsService $settings):void{abort_unless((bool)$settings->setting()->optimization_enabled,409,'Choice Optimization is disabled for this examination.');}
    private function assertGoogleFormEnabled(ChoiceOptimizationSettingsService $settings):void{$this->assertOptimizationEnabled($settings);abort_unless($settings->setting()->google_form_enabled===true,409,'Google Form historical recommendation step is not enabled.');}
}
